CREATE DATABASE IF NOT EXISTS kubar_vastu CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE kubar_vastu;
CREATE TABLE IF NOT EXISTS users (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(120) NOT NULL,gender VARCHAR(30) NOT NULL DEFAULT '',email VARCHAR(190) NOT NULL UNIQUE,phone VARCHAR(30) NOT NULL DEFAULT '',place VARCHAR(120) NOT NULL DEFAULT '',user_type VARCHAR(80) NOT NULL DEFAULT '',username VARCHAR(100) NULL UNIQUE,password_hash VARCHAR(255) NOT NULL,last_login_at DATETIME NULL,last_logout_at DATETIME NULL,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS sessions (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id BIGINT UNSIGNED NOT NULL,token_hash CHAR(64) NOT NULL UNIQUE,expires_at DATETIME NOT NULL,revoked_at DATETIME NULL,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT fk_sessions_user FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE,INDEX idx_sessions_expiry(expires_at)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS admin_sessions (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,token_hash CHAR(64) NOT NULL UNIQUE,expires_at DATETIME NOT NULL,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,INDEX idx_admin_expiry(expires_at)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS remedies (id VARCHAR(100) PRIMARY KEY,title VARCHAR(190) NOT NULL,subtitle VARCHAR(255) NOT NULL DEFAULT '',direction VARCHAR(100) NOT NULL,purpose TEXT NOT NULL,category VARCHAR(120) NOT NULL DEFAULT 'General Remedies',price DECIMAL(10,2) NOT NULL DEFAULT 0,why_you_need TEXT NULL,how_it_works TEXT NULL,what_you_get TEXT NULL,placement TEXT NULL,offers JSON NULL,image_urls JSON NULL,video_urls JSON NULL,installation_image_urls JSON NULL,installation_video_urls JSON NULL,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS orders (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id BIGINT UNSIGNED NOT NULL,remedy_id VARCHAR(100) NOT NULL,remedy_name VARCHAR(190) NOT NULL,quantity INT NOT NULL DEFAULT 1,unit_price DECIMAL(10,2) NOT NULL DEFAULT 0,price DECIMAL(10,2) NOT NULL DEFAULT 0,status VARCHAR(30) NOT NULL DEFAULT 'created',purchased_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,validity_starts_at DATETIME NULL,validity_ends_at DATETIME NULL,payment_id VARCHAR(190) NOT NULL DEFAULT '',created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT fk_orders_user FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE,INDEX idx_orders_user(user_id),INDEX idx_orders_payment(payment_id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS purchases (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id BIGINT UNSIGNED NOT NULL,items JSON NOT NULL,total DECIMAL(10,2) NOT NULL,currency CHAR(3) NOT NULL DEFAULT 'INR',status ENUM('pending','paid','failed') NOT NULL DEFAULT 'pending',checkout_token_hash CHAR(64) NOT NULL UNIQUE,razorpay_order_id VARCHAR(190) NOT NULL UNIQUE,razorpay_payment_id VARCHAR(190) NOT NULL DEFAULT '',paid_at DATETIME NULL,validity_ends_at DATETIME NULL,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT fk_purchases_user FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS app_updates (id TINYINT UNSIGNED PRIMARY KEY DEFAULT 1,enabled TINYINT(1) NOT NULL DEFAULT 1,latest_version VARCHAR(30) NOT NULL DEFAULT '1.0.0',latest_build_number INT NOT NULL DEFAULT 1,download_url TEXT NULL,release_notes TEXT NULL,force_update TINYINT(1) NOT NULL DEFAULT 0,updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP) ENGINE=InnoDB;
INSERT IGNORE INTO app_updates(id,release_notes) VALUES(1,'A new Kubar Vastu app update is available.');
CREATE TABLE IF NOT EXISTS blogs (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,title VARCHAR(255) NOT NULL,description TEXT NOT NULL,content LONGTEXT NOT NULL,image_url TEXT NULL,category VARCHAR(100) NOT NULL DEFAULT 'Vastu',published TINYINT(1) NOT NULL DEFAULT 1,published_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,INDEX idx_blogs_published(published,published_at)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS testimonials (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(120) NOT NULL,profile_image_url TEXT NULL,rating TINYINT UNSIGNED NOT NULL DEFAULT 5,review TEXT NOT NULL,status ENUM('pending','approved','rejected') NOT NULL DEFAULT 'pending',created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,INDEX idx_testimonials_status(status,created_at)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS videos (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,video_id VARCHAR(20) NOT NULL UNIQUE,title VARCHAR(255) NOT NULL,thumbnail_url TEXT NULL,published TINYINT(1) NOT NULL DEFAULT 1,published_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP) ENGINE=InnoDB;

